import { ALPHABET, charToValue } from './alphabet.mjs';

export function b58encodeInt(v) {
  if (v < 0n) {
    throw new Error("can't encode negative integer");
  }
  if (v === 0n) {
    return '1';
  }
  let result = '';
  while (v > 0n) {
    const rem = v % 58n;
    v = v / 58n;
    result = ALPHABET[Number(rem)] + result;
  }
  return result;
}

export function b58decodeInt(s) {
  let acc = 0n;
  for (const ch of s) {
    const value = charToValue(ch);
    if (value === null) {
      throw new Error(`Invalid character '${ch}'`);
    }
    acc = acc * 58n + value;
  }
  return acc;
}

