// Formatting helpers that reproduce CPython's repr() of a bytes object
// and plain decimal formatting of a BigInt.

/**
 * Return the Python repr() of a bytes object built from the ASCII string s.
 * Quote selection and escaping follow CPython's bytes_repr:
 * - default quote is a single quote; double quotes are used only when s
 *   contains a single quote but no double quote
 * - backslash and the active quote char are escaped with a backslash
 * - \t, \n, \r get their two-letter escapes
 * - any other byte outside printable ASCII 0x20-0x7E becomes \xNN
 *   (lowercase hex)
 */
export function bytesRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (const ch of s) {
    const code = ch.charCodeAt(0);
    if (ch === '\\' || ch === quote) {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (code >= 0x20 && code <= 0x7e) {
      out += ch;
    } else {
      out += '\\x' + code.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

/**
 * Return the decimal string of a BigInt, matching Python's int -> str.
 */
export function formatInt(v) {
  return v.toString();
}

