import { parseArgs } from './lib/args.mjs';
import { b58encodeInt, b58decodeInt } from './lib/base58.mjs';
import { bytesRepr, formatInt } from './lib/pyformat.mjs';

const args = parseArgs(process.argv.slice(2));

try {
  // Compute everything before printing anything: a codec failure must
  // leave stdout empty, just like the Python original.
  const encoded1 = b58encodeInt(args.a);
  const encoded2 = b58encodeInt(args.b);
  const decoded = b58decodeInt(args.c);

  console.log(bytesRepr(encoded1));
  console.log(bytesRepr(encoded2));
  console.log(formatInt(decoded));
} catch (e) {
  const excType = e.message.startsWith("can't encode") ? 'TypeError' : 'ValueError';
  process.stderr.write('Traceback (most recent call last):\n');
  process.stderr.write(`${excType}: ${e.message}\n`);
  process.exit(1);
}

