eq(charToValue('0'), null, 'charToValue(0) null');

const encCases = [
  [10000n, '3yR'],
  [262631383n, 'QD4AJ'],
  [255n, '5Q'],
  [100n, '2j'],
  [1000000n, '68GP'],
  [1n, '2'],
  [0n, '1'],
  [123456789012345678901234567890n, '8XcTm1rhDaaCfzETs'],
  [58n, '21'],
