// Argument parser for test14.mjs, replicating Python argparse behavior
// for three required options: --a (int), --b (int), --c (str).

const PROG = 'test14.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C`;

const HELP = `${USAGE}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
`;

// Mirrors Python int(): surrounding whitespace trimmed, optional +/- sign,
// digits only.
const INT_RE = /^[+-]?\d+$/;

// A token that starts with '-' is still treated as a value when it looks
// like a negative number (argparse's _negative_number_matcher behavior).
const NEGATIVE_NUMBER_RE = /^-\d+$/;

function error(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(HELP);
  process.exit(0);
}

function parseIntValue(optionName, raw) {
  const text = raw.trim();
  if (!INT_RE.test(text)) {
    error(`argument ${optionName}: invalid int value: '${raw}'`);
  }
  return BigInt(text);
}

function looksLikeOption(token) {
  if (token === '-' || token === '') return false;
  if (!token.startsWith('-')) return false;
  if (NEGATIVE_NUMBER_RE.test(token)) return false;
  return true;
}

export function parseArgs(argv) {
  const values = { a: undefined, b: undefined, c: undefined };
  const seen = new Set();
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp();
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);

      if (name === '--a' || name === '--b' || name === '--c') {
        const key = name.slice(2);
        let raw;
        if (eq !== -1) {
          raw = token.slice(eq + 1);
        } else {
          const next = argv[i + 1];
          if (next === undefined || looksLikeOption(next)) {
            error(`argument ${name}: expected one argument`);
          }
          raw = next;
          i += 1;
        }
        seen.add(key);
        if (key === 'c') {
          values.c = raw;
        } else {
          values[key] = parseIntValue(name, raw);
        }
      } else {
        extras.push(token);
      }
    } else {
      extras.push(token);
    }
    i += 1;
  }

  // argparse checks required arguments (inside parse_known_args) before
  // reporting unrecognized arguments (in parse_args).
  const missing = [];
  if (!seen.has('a')) missing.push('--a');
  if (!seen.has('b')) missing.push('--b');
  if (!seen.has('c')) missing.push('--c');
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b, c: values.c };
}

